import{z as B,x as R,o as A,c as n,q as l,j as t,D as E,d as e,s as o,S as s,b as L}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"SLR 与 LALR","description":"","frontmatter":{"title":"SLR 与 LALR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/slr-lalr.md","filePath":"cs/slr-lalr.md","lastUpdated":1791063341000}'),i={name:"cs/slr-lalr.md"};function d(p,a,m,S,c,h){const r=R("Mermaid");return A(),n("div",null,[a[2]||(a[2]=l('<h1 id="slr-与-lalr" tabindex="-1">SLR 与 LALR <a class="header-anchor" href="#slr-与-lalr" aria-label="Permalink to &quot;SLR 与 LALR&quot;">​</a></h1><div class="epigraph"><p>同一张项集规范族上，SLR 用 FOLLOW 决定归约，LALR 把 LR(1) 项按芯合并；表更小，认的语言夹在 SLR 与 LR(1) 之间。</p><footer>—— 据 DeRemer, Simple LR(k) Grammars, 1971；DeRemer and Pennello, Efficient Computation of LALR(1) Look-Ahead Sets, 1982；龙书第 4 章整理</footer></div><p>上一课<a href="/cs/lr-shift-reduce">LR 与移进归约</a>给出项、闭包、GOTO、移进/归约冲突，并声明 SLR 用 FOLLOW、LALR 是 Yacc 的实用点，没有填表。本课不重画最右推导。缺口是三种表的差别：SLR(1)、LALR(1)、LR(1)——状态怎么增，冲突怎么少。归约时可挂语义动作，下一课 AST 就在这里接。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LR(0) 项不带前瞻，同一状态里两条完成项就会归约/归约冲突。SLR：完成项 \\(A\\to\\alpha\\cdot\\) 只对 \\(a\\in\\mathrm{FOLLOW}(A)\\) 归约。FOLLOW 是粗前瞻，可能仍冲突。LR(1) 项 \\([A\\to\\alpha\\cdot\\beta,a]\\) 把前瞻钉在项上，状态变多，冲突最少（在确定 CFG 的实用范围内）。LALR：把芯（忽略前瞻的 LR(0) 部分）相同的 LR(1) 状态合并，前瞻取并。状态数约等于 LR(0) 族，前瞻比 SLR 细。</p><p>缺口是这层包含：\\(\\mathrm{SLR}\\subset\\mathrm{LALR}\\subset\\mathrm{LR}(1)\\)（能无冲突分析的文法类）。Yacc/bison 默认 LALR(1)。if-else 仍常要 <code>%left</code>/<code>%nonassoc</code> 人工消二义，LALR 本身并不消去二义。</p><h3 id="合并可能引入新冲突" tabindex="-1">合并可能引入新冲突 <a class="header-anchor" href="#合并可能引入新冲突" aria-label="Permalink to &quot;合并可能引入新冲突&quot;">​</a></h3><p>两个 LR(1) 状态芯同、前瞻不同，合并后可能在同一完成项上多出一个不该归约的符号。故存在 LALR 冲突而规范 LR(1) 无冲突的文法。本课承认，不构造病态长例。</p><p><span class="marginnote">DeRemer 的 SLR 与 LALR。龙书 4.6–4.7 节比较表大小。Knuth LR(\\(k\\)) 是上一课总框架。本课要生成器选哪张表，不手填 GOTO 全表。</span></p><p><span class="marginnote">术语翻译：三张表都在回答同一个问题「遇到符号 \\(a\\)，此刻该移进还是归约」。SLR 查的是「\\(A\\) 后面<strong>任何地方</strong>可能出现什么」（FOLLOW，粗）；LR(1) 查的是「<strong>在这个位置</strong>走完这条产生式后能见什么」（项上钉死的前瞻，细）；LALR 取中间——位置对，但把长相差不多的位置合并成一格、前瞻取并集。</span></p><p><span class="marginnote">数字实例：一门课程规模的文法，LR(0) 项集族约几十个状态，规范 LR(1) 可以膨胀到上千（同一批项按不同前瞻反复复制），LALR 合并后回落到与 LR(0) 同量级的几百——这正是 Yacc 能装进 1970 年代内存的原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从增广文法建 LR(0) 项集（SLR/LALR 的芯）。SLR：归约栏填 FOLLOW。要 LALR：传播前瞻（DeRemer–Pennello）或先 LR(1) 再合并。冲突仍在则改文法或加优先级。</p>',13)),(A(),t(s,null,{default:E(()=>[o(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IT%5B%22%E9%A1%B9%E9%9B%86%E6%97%8F%22%5D%20--%3E%20SLR%5B%22SLR%EF%BC%9AFOLLOW%20%E5%BD%92%E7%BA%A6%22%5D%0A%20%20IT%20--%3E%20LALR%5B%22LALR%EF%BC%9A%E5%90%88%E5%B9%B6%E8%8A%AF%20%2B%20%E5%B9%B6%E5%89%8D%E7%9E%BB%22%5D%0A%20%20IT%20--%3E%20LR1%5B%22LR(1)%EF%BC%9A%E9%A1%B9%E8%87%AA%E5%B8%A6%20a%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=L("p",null,[e("分析循环与上一课相同：查动作表直到接受。归约 \\(A\\to\\alpha\\) 时执行用户动作："),L("code",null,"new"),e(" AST 节点——对象下一课才定义，本课只留挂钩。")],-1)),a[4]||(a[4]=L("h2",{id:"机制",tabindex:"-1"},[e("机制 "),L("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=L("p",null,"左递归对三族都友好。表的体积：LR(1) 可能上千态，LALR 几百，够一门课的语言。错误恢复（恐慌模式丢记号）是生成器附加，本课点名。",-1)),a[6]||(a[6]=L("p",null,"「同一个文法，SLR 报冲突、LALR 却能过」是怎么发生的？前瞻由粗到细，冲突逐级消解：",-1)),(A(),t(s,null,{default:E(()=>[o(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%90%8C%E4%B8%80%E6%96%87%E6%B3%95%E7%9A%84%E5%AE%8C%E6%88%90%E9%A1%B9%20A%E2%86%92%CE%B1%C2%B7%22%5D%20--%3E%20S%7B%22SLR%EF%BC%9Aa%20%E2%88%88%20FOLLOW(A)%3F%22%7D%0A%20%20S%20--%20%22FOLLOW%20%E5%A4%AA%E5%AE%BD%3Cbr%3E%E6%92%9E%E4%B8%8A%E7%A7%BB%E8%BF%9B%22%20--%3E%20C1%5B%22%E6%8A%A5%E7%A7%BB%E8%BF%9B%2F%E5%BD%92%E7%BA%A6%E5%86%B2%E7%AA%81%22%5D%0A%20%20S%20--%20%E6%81%B0%E5%A5%BD%E6%97%A0%E6%92%9E%20--%3E%20OK1%5B%22SLR%20%E8%A1%A8%E8%83%BD%E7%94%A8%22%5D%0A%20%20G%20--%3E%20L%7B%22LALR%EF%BC%9A%E5%90%88%E5%B9%B6%E5%90%8E%EF%BC%9Cbr%EF%BC%9Ea%20%E5%9C%A8%E9%A1%B9%E7%9A%84%E5%89%8D%E7%9E%BB%E9%87%8C%3F%22%7D%0A%20%20L%20--%20%22%E5%8F%AA%E5%9C%A8%E8%AF%A5%E4%BD%8D%E7%BD%AE%E5%8F%AF%E8%83%BD%E5%87%BA%E7%8E%B0%22%20--%3E%20OK2%5B%22%E5%BD%92%E7%BA%A6%E6%A0%8F%E5%8F%AA%E5%A1%AB%20a%3Cbr%3E%E5%86%B2%E7%AA%81%E6%B6%88%E5%A4%B1%22%5D%0A%20%20L%20--%20%22%E5%90%88%E5%B9%B6%E5%B9%B6%E9%9B%86%E4%BB%8D%E6%92%9E%22%20--%3E%20C2%5B%22%E4%BB%8D%E5%86%B2%E7%AA%81%EF%BC%9A%E6%94%B9%E6%96%87%E6%B3%95%E6%88%96%E5%8A%A0%E4%BC%98%E5%85%88%E7%BA%A7%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>这一步如果理解偏了，会把 FOLLOW 用反：初学者常拿 FOLLOW 去管「产生式右边第一个能是什么」，那是 FIRST 的活。FOLLOW 只回答「\\(A\\) 整体推完后，下一个符号可以是哪些」——它管归约时机，不管推导起点。</p><p>不要把 FOLLOW 当 FIRST：FOLLOW 管「A 推完后后面能见什么」，归约用它。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列出闭包伪代码全文，不处理 GLR。后课默认：实用语法用 LALR/SLR 表驱动；归约动作构造抽象语法树，丢掉分层非终结符。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SLR 用 FOLLOW；LR(1) 项带前瞻；LALR 合并芯。</li><li>文法类 SLR ⊂ LALR ⊂ LR(1)；Yacc 用 LALR。</li><li>归约挂钩给下一课 AST。</li><li>出处：DeRemer, 1971；DeRemer and Pennello, 1982；龙书第 4 章。</li></ul>',6))])}const O=B(i,[["render",d]]);export{D as __pageData,O as default};
